async function run(){await db.initialize();console.log("Database initialized.");const e=db.models.settings;if(e){const t=await e.findOne({where:{key:"binarySettings"}});if(t){const a=JSON.parse(t.value);if(a.display){a.display.chartType="CHART_ENGINE";a._lastModified=(new Date).toISOString();await e.update({value:JSON.stringify(a)},{where:{key:"binarySettings"}});console.log("Updated binarySettings display.chartType to TRADINGVIEW.")}}else console.log("binarySettings not found!");if(await e.findOne({where:{key:"spotChartEngine"}})){await e.update({value:"CHART_ENGINE"},{where:{key:"spotChartEngine"}});console.log("Updated spotChartEngine value to TRADINGVIEW.")}else console.log("spotChartEngine not found!");try{const{CacheManager:e}=require("@b/utils/cache"),t=e.getInstance();await t.clearCache();console.log("Cache cleared.")}catch(e){console.log("Could not clear cache via CacheManager (possibly not active or different path):",e.message)}}else console.error("Settings model not found!");process.exit(0)}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db");run().catch(e=>{console.error(e);process.exit(1)});